import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import type React from 'react';
import { useEffect, useMemo, useRef, useState } from 'react';
import { uploadSeatConfig } from '@/api/ai-server';
import type { Settings } from '@/api/settings';
import { settingsApi } from '@/api/settings';
import { useNotification } from '@/components/notification';
import {
  fetchModelListWithFallback,
  invalidateLocalModelCache,
  invalidateServerModelCache,
} from '@/lib/ai-config-provider';
import { extractAiCredentials } from '@/lib/ai-credentials';
import { LoadingSpinner } from '../common/loading-spinner';
import { AiConfigSection } from './ai-config-section';
import { PostTypesSection } from './post-types-section';

export const AiSettingsTab: React.FC = () => {
  const { notify } = useNotification();
  const queryClient = useQueryClient();
  const [formData, setFormData] = useState<Settings | null>(null);
  const [isPreparingSave, setIsPreparingSave] = useState(false);

  // 获取设置
  const { data, isLoading } = useQuery({
    queryKey: ['settings'],
    queryFn: settingsApi.get,
  });

  // 更新设置
  const updateMutation = useMutation({
    mutationFn: settingsApi.update,
    onSuccess: (response) => {
      notify('success', response.message);
      // Update global bootstrap for immediate consumers still reading window
      try {
        const w: any = window as any;
        if (w.zeroySettings) {
          w.zeroySettings.settings =
            response.settings || w.zeroySettings.settings;
        }
      } catch {
        // Ignore
      }
      queryClient.invalidateQueries({ queryKey: ['settings'] });
      invalidateLocalModelCache();
      invalidateServerModelCache();
      queryClient.invalidateQueries({ queryKey: ['server-ai-config'] });
      setFormData(null);
    },
    onError: () => {
      notify('error', '保存失败，请重试');
    },
  });

  // 重置设置
  const resetMutation = useMutation({
    mutationFn: settingsApi.reset,
    onSuccess: (response) => {
      notify('success', response.message);
      queryClient.invalidateQueries({ queryKey: ['settings'] });
      invalidateLocalModelCache();
      invalidateServerModelCache();
      queryClient.invalidateQueries({ queryKey: ['server-ai-config'] });
      setFormData(null);
    },
    onError: () => {
      notify('error', '重置失败，请重试');
    },
  });

  const remoteSettings = data?.settings;

  // 使用表单数据或从服务器获取的数据
  const settings = formData || remoteSettings;

  const credentials = useMemo(() => extractAiCredentials(settings), [settings]);
  const { apiToken, baseUrl, apiKey } = credentials;

  const {
    data: serverConfig,
    isLoading: isServerConfigInitialLoading,
    isFetching: isServerConfigFetching,
    refetch: refetchServerConfig,
  } = useQuery({
    queryKey: ['server-ai-config', apiToken, baseUrl, apiKey],
    queryFn: () =>
      fetchModelListWithFallback({
        apiToken: apiToken || undefined,
        baseUrl: baseUrl || undefined,
        apiKey: apiKey || undefined,
      }),
    enabled: Boolean(apiToken || (baseUrl && apiKey)),
    staleTime: 60 * 1000,
  });

  const isServerConfigLoading =
    isServerConfigInitialLoading || isServerConfigFetching;

  const handleRefreshServerConfig = () => {
    invalidateServerModelCache();
    if (credentials.hasCredentials) {
      refetchServerConfig();
    }
  };

  // 进入页面时自动刷新一次服务端配置（仅触发一次）
  const didInitialRefresh = useRef(false);
  useEffect(() => {
    if (didInitialRefresh.current) {
      return;
    }
    if (credentials.hasCredentials) {
      didInitialRefresh.current = true;
      invalidateServerModelCache();
      refetchServerConfig();
    }
  }, [credentials.hasCredentials, refetchServerConfig]);

  // 页面加载时自动同步本地凭据到云端（静默执行，仅一次）
  const didAutoSync = useRef(false);
  useEffect(() => {
    // 已经同步过，跳过
    if (didAutoSync.current) {
      return;
    }

    // 等待服务端配置加载完成
    if (isServerConfigLoading || !serverConfig) {
      return;
    }

    // 检查是否需要自动同步：有 token + 本地有凭据 + 云端未配置
    const shouldAutoSync =
      credentials.hasToken &&
      credentials.hasLocalKey &&
      !serverConfig.serverConfigured;

    if (shouldAutoSync) {
      // 静默上传到云端（不显示通知，不打断用户）
      uploadSeatConfig(credentials.apiToken, {
        baseUrl: credentials.baseUrl,
        apiKey: credentials.apiKey,
      })
        .then(() => {
          // 同步成功后才标记，避免失败时无法重试
          didAutoSync.current = true;
          // 同步成功后刷新云端配置
          invalidateServerModelCache();
          queryClient.invalidateQueries({ queryKey: ['server-ai-config'] });
          refetchServerConfig();
        })
        .catch(() => {
          // 静默失败，不标记 didAutoSync，下次刷新页面会重试
        });
    }
  }, [
    isServerConfigLoading,
    serverConfig,
    credentials,
    queryClient,
    refetchServerConfig,
  ]);

  const handleChange = (field: keyof Settings, value: any) => {
    if (!settings) {
      return;
    }

    // 禁止修改 API URL 和 API Key（云端管理）
    if (field === 'base_url' || field === 'api_key') {
      return;
    }

    setFormData({
      ...settings,
      [field]: value,
    });
  };

  const handlePostTypeToggle = (postType: string) => {
    if (!settings) {
      return;
    }

    const newPostTypes = settings.post_types.includes(postType)
      ? settings.post_types.filter((pt) => pt !== postType)
      : [...settings.post_types, postType];

    handleChange('post_types', newPostTypes);
  };

  const omitCredentialFields = (source: Partial<Settings>) => {
    // 总是移除凭据字段，由云端管理
    // 使用解构赋值完全移除字段，避免发送 undefined 导致后端清空数据
    const { base_url: _baseUrl, api_key: _apiKey, ...next } = source;
    return next;
  };

  const prepareCredentialSafePayload = (
    rawPayload: Partial<Settings>
  ): Partial<Settings> => {
    // 总是移除凭据字段，不再支持在 WP 端保存
    return omitCredentialFields(rawPayload);
  };

  const handleSave = async () => {
    if (!formData) {
      notify('info', '没有修改需要保存');
      return;
    }
    setIsPreparingSave(true);

    try {
      const payload = prepareCredentialSafePayload(formData);
      await updateMutation.mutateAsync(payload);
    } catch (_error) {
      // updateMutation 会负责提示保存错误
    } finally {
      setIsPreparingSave(false);
    }
  };

  const handleReset = () => {
    if (window.confirm('确定要重置所有设置为默认值吗？')) {
      resetMutation.mutate();
    }
  };

  if (isLoading) {
    return <LoadingSpinner message="加载 AI 设置中..." />;
  }

  if (!(settings && data)) {
    return (
      <div className="flex h-64 items-center justify-center">
        <div className="text-red-500">加载设置失败</div>
      </div>
    );
  }

  const hasChanges = formData !== null;
  const isSaving =
    isPreparingSave || updateMutation.isPending || resetMutation.isPending;

  return (
    <div className="space-y-8">
      {/* 操作按钮 */}
      <div className="flex items-center justify-between rounded-xl border border-gray-200 bg-white p-6 shadow-sm">
        <button
          className="inline-flex items-center space-x-2 rounded-lg border border-gray-300 bg-white px-5 py-2.5 font-medium text-gray-700 transition-colors hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-50"
          disabled={isSaving}
          onClick={handleReset}
          type="button"
        >
          <svg
            className="h-4 w-4"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <title>Reset icon</title>
            <path
              d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
            />
          </svg>
          <span>重置为默认值</span>
        </button>

        <button
          className={`inline-flex items-center space-x-2 rounded-lg px-6 py-2.5 font-medium transition-colors ${
            hasChanges && !isSaving
              ? 'bg-blue-600 text-white hover:bg-blue-700'
              : 'cursor-not-allowed bg-gray-100 text-gray-400'
          }`}
          disabled={!hasChanges || isSaving}
          onClick={handleSave}
          type="button"
        >
          {isSaving ? (
            <>
              <div className="h-4 w-4 animate-spin rounded-full border-2 border-white border-t-transparent" />
              <span>保存中...</span>
            </>
          ) : (
            <>
              <svg
                className="h-4 w-4"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <title>Check icon</title>
                <path
                  d="M5 13l4 4L19 7"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                />
              </svg>
              <span>保存设置</span>
            </>
          )}
        </button>
      </div>

      <AiConfigSection
        isServerConfigLoading={isServerConfigLoading}
        onChange={handleChange}
        onRefreshServerConfig={handleRefreshServerConfig}
        serverConfig={serverConfig}
        settings={settings}
      />

      <PostTypesSection
        onPostTypeToggle={handlePostTypeToggle}
        postTypes={data.postTypes}
        settings={settings}
      />
    </div>
  );
};
