import type React from 'react';
import type { Settings } from '@/api/settings';
import type { ModelListResult } from '@/lib/ai-config-provider';
import { extractAiCredentials } from '@/lib/ai-credentials';

interface AiConfigSectionProps {
  settings: Settings;
  onChange: (field: keyof Settings, value: any) => void;
  serverConfig?: ModelListResult;
  isServerConfigLoading: boolean;
  onRefreshServerConfig: () => void;
}

export const AiConfigSection: React.FC<AiConfigSectionProps> = ({
  settings,
  onChange,
  serverConfig,
  isServerConfigLoading,
  onRefreshServerConfig,
}) => {
  const additionalContextLength = settings.additional_context?.length || 0;
  const credentials = extractAiCredentials(settings);

  const serverStatus = serverConfig?.serverStatus;
  const isServerManaged = Boolean(
    serverConfig?.serverConfigured && serverConfig?.baseUrl
  );
  const serverErrorMessage = serverConfig?.serverErrorMessage;
  const modelsCount = serverConfig?.models.length ?? 0;

  const renderLoadingStatus = () => (
    <div className="mb-6 rounded-lg border border-gray-200 bg-gray-50 p-4 text-gray-600 text-sm">
      <div className="flex items-center gap-3">
        <div className="h-4 w-4 animate-spin rounded-full border-2 border-gray-400 border-t-transparent" />
        <span>正在检查服务端配置...</span>
      </div>
    </div>
  );

  const renderManagedStatus = () => {
    const isEmpty = modelsCount === 0;
    const cardBorder = isEmpty ? 'border-amber-200' : 'border-green-200';
    const cardBg = isEmpty ? 'bg-amber-50' : 'bg-green-50';
    const titleColor = isEmpty ? 'text-amber-800' : 'text-green-800';
    const textColor = isEmpty ? 'text-amber-700' : 'text-green-700';
    const dtColor = isEmpty ? 'text-amber-600' : 'text-green-600';

    return (
      <div className={`mb-6 rounded-lg border ${cardBorder} ${cardBg} p-4`}>
        <div className="flex flex-col gap-3">
          <div>
            <p className={`font-medium ${titleColor}`}>服务端托管已启用</p>
            <p className={`mt-1 ${textColor} text-sm`}>
              当前凭据由服务端托管，插件已使用最新的模型列表。
            </p>
            <dl className={`mt-3 space-y-1 ${textColor} text-sm`}>
              <div className="flex gap-2">
                <dt className={`w-16 shrink-0 ${dtColor}`}>供应商</dt>
                <dd>{serverConfig?.provider || '—'}</dd>
              </div>
              <div className="flex gap-2">
                <dt className={`w-16 shrink-0 ${dtColor}`}>Base URL</dt>
                <dd className="break-all">{serverConfig?.baseUrl || '—'}</dd>
              </div>
              <div className="flex gap-2">
                <dt className={`w-16 shrink-0 ${dtColor}`}>模型数</dt>
                <dd>{modelsCount}</dd>
              </div>
              {serverConfig?.fetchedAt && (
                <div className="flex gap-2">
                  <dt className={`w-16 shrink-0 ${dtColor}`}>拉取时间</dt>
                  <dd>{new Date(serverConfig.fetchedAt).toLocaleString()}</dd>
                </div>
              )}
              {serverConfig?.expiresAt && (
                <div className="flex gap-2">
                  <dt className={`w-16 shrink-0 ${dtColor}`}>缓存到期</dt>
                  <dd>{new Date(serverConfig.expiresAt).toLocaleString()}</dd>
                </div>
              )}
              {isEmpty && (
                <div className="flex gap-2">
                  <dt className={`w-16 shrink-0 ${dtColor}`}>提示</dt>
                  <dd>未拉取到模型，稍后会自动更新。</dd>
                </div>
              )}
            </dl>
          </div>
        </div>
      </div>
    );
  };

  const renderErrorStatus = () => (
    <div className="mb-6 rounded-lg border border-red-200 bg-red-50 p-4 text-red-700 text-sm">
      <div className="flex flex-col gap-3 md:flex-row md:items-start md:justify-between">
        <div>
          <p className="font-medium text-red-800">服务端配置暂时不可用</p>
          <p className="mt-1">
            {serverErrorMessage || '请求服务端模型列表失败'}
          </p>
        </div>
        <div className="flex flex-wrap gap-2">
          <button
            className="inline-flex items-center space-x-2 rounded-lg border border-red-200 bg-white px-4 py-2 font-medium text-red-700 text-sm transition-colors hover:bg-red-100 disabled:cursor-not-allowed disabled:opacity-50"
            disabled={isServerConfigLoading}
            onClick={onRefreshServerConfig}
            type="button"
          >
            <svg
              className="h-4 w-4"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <title>刷新</title>
              <path
                d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
              />
            </svg>
            <span>重试</span>
          </button>
        </div>
      </div>
    </div>
  );

  const renderCloudConfigRequired = () => (
    <div className="mb-6 rounded-lg border border-blue-200 bg-blue-50 p-4">
      <div className="flex flex-col gap-3">
        <div>
          <p className="font-medium text-blue-900">需要配置 AI 服务</p>
          <p className="mt-1 text-blue-700 text-sm">
            请前往{' '}
            <a
              className="font-medium underline hover:text-blue-800"
              href="https://www.zeroy.app/dashboard"
              rel="noopener noreferrer"
              target="_blank"
            >
              zeroy.app
            </a>{' '}
            配置您的 AI 服务凭据，配置完成后点击下方"刷新配置"按钮。
          </p>
        </div>
        <div>
          <button
            className="inline-flex items-center space-x-2 rounded-lg border border-blue-300 bg-white px-4 py-2 font-medium text-blue-700 text-sm transition-colors hover:bg-blue-100 disabled:cursor-not-allowed disabled:opacity-50"
            disabled={isServerConfigLoading}
            onClick={onRefreshServerConfig}
            type="button"
          >
            <svg
              className="h-4 w-4"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <title>刷新</title>
              <path
                d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
              />
            </svg>
            <span>刷新配置</span>
          </button>
        </div>
      </div>
    </div>
  );

  const renderStatusPanel = () => {
    if (isServerConfigLoading) {
      return renderLoadingStatus();
    }
    if (isServerManaged) {
      return renderManagedStatus();
    }
    if (serverStatus === 'error') {
      return renderErrorStatus();
    }
    // 两边都没有配置：云端未配置 && 本地也没有凭据
    if (!(isServerManaged || credentials.hasLocalKey)) {
      return renderCloudConfigRequired();
    }
    return null;
  };

  const statusPanel = renderStatusPanel();

  return (
    <div className="rounded-xl border border-gray-200 bg-white p-8 shadow-sm">
      <div className="mb-8">
        <h2 className="font-semibold text-gray-900 text-xl">AI 配置</h2>
        <p className="mt-1 text-gray-600 text-sm">配置 AI 服务的连接参数</p>
      </div>

      {statusPanel}

      <div className="space-y-6">
        <div>
          <label
            className="mb-3 block font-medium text-gray-700"
            htmlFor="additional-context"
          >
            补充上下文
          </label>
          <div className="relative">
            <textarea
              className="w-full rounded-lg border border-gray-300 bg-gray-50 px-4 py-3 pr-20 text-sm transition-colors focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-500/20"
              id="additional-context"
              maxLength={10_000}
              onChange={(e) => onChange('additional_context', e.target.value)}
              placeholder="例如：我们是一家专注于健康食品的电商网站，目标受众是25-45岁的都市白领..."
              rows={4}
              value={settings.additional_context || ''}
            />
            <div className="absolute right-3 bottom-2 text-gray-400 text-xs">
              <span
                className={`${additionalContextLength > 9500 ? 'font-medium text-orange-500' : ''}`}
              >
                {additionalContextLength}
              </span>
              <span className="text-gray-400"> / 10000</span>
            </div>
          </div>
          <p className="mt-2 text-gray-500 text-sm">
            提供关于您的业务、目标受众、品牌调性等背景信息，AI
            将根据这些信息生成更贴合的内容
          </p>
        </div>
      </div>
    </div>
  );
};
