import { ChevronDown } from 'lucide-react';
import type React from 'react';
import { useState } from 'react';
import type { PostType, Settings } from '@/api/settings';

interface PostTypesSectionProps {
  settings: Settings;
  postTypes: PostType[];
  onPostTypeToggle: (postType: string) => void;
}

export const PostTypesSection: React.FC<PostTypesSectionProps> = ({
  settings,
  postTypes,
  onPostTypeToggle,
}) => {
  const [isExpanded, setIsExpanded] = useState(false);

  return (
    <div className="overflow-hidden rounded-xl border border-gray-200 bg-white shadow-sm">
      <button
        className="flex w-full items-center justify-between p-8 text-left transition-colors hover:bg-gray-50"
        onClick={() => setIsExpanded(!isExpanded)}
        type="button"
      >
        <div>
          <h2 className="font-semibold text-gray-900 text-xl">
            支持的内容类型
          </h2>
          <p className="mt-1 text-gray-600 text-sm">
            默认仅对"页面"启用，通常不需要修改
          </p>
        </div>
        <ChevronDown
          className={`h-5 w-5 text-gray-400 transition-transform ${
            isExpanded ? 'rotate-180 transform' : ''
          }`}
        />
      </button>

      {isExpanded && (
        <div className="border-gray-100 border-t px-8 pb-8">
          <div className="grid gap-4 pt-6 sm:grid-cols-2 lg:grid-cols-3">
            {postTypes.map((postType) => (
              <label
                className="group relative flex cursor-pointer items-center space-x-3 rounded-lg border border-gray-200 p-4 transition-all hover:border-blue-300 hover:bg-blue-50/50"
                key={postType.name}
              >
                <input
                  checked={settings.post_types.includes(postType.name)}
                  className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-2 focus:ring-blue-500 focus:ring-offset-0"
                  onChange={() => onPostTypeToggle(postType.name)}
                  type="checkbox"
                />
                <div className="ml-2 min-w-0 flex-1">
                  <div className="font-medium text-gray-900 text-sm">
                    {postType.label}
                  </div>
                  <div className="text-gray-500 text-xs">{postType.name}</div>
                </div>
                <div
                  className={`absolute inset-0 rounded-lg transition-all ${
                    settings.post_types.includes(postType.name)
                      ? 'ring-2 ring-blue-500 ring-offset-2'
                      : ''
                  }`}
                />
              </label>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};
